import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"SaaS Laravel Starter Kits FAQ","description":"Answers to common questions about the SaaS Laravel starter kits: kit differences, features, pricing, repository access, updates and development.","frontmatter":{"title":"SaaS Laravel Starter Kits FAQ","description":"Answers to common questions about the SaaS Laravel starter kits: kit differences, features, pricing, repository access, updates and development.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/reference/faq.html"}],["meta",{"property":"og:title","content":"SaaS Laravel Starter Kits FAQ"}],["meta",{"property":"og:description","content":"Answers to common questions about the SaaS Laravel starter kits: kit differences, features, pricing, repository access, updates and development."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/reference/faq.html"}],["meta",{"name":"twitter:title","content":"SaaS Laravel Starter Kits FAQ"}],["meta",{"name":"twitter:description","content":"Answers to common questions about the SaaS Laravel starter kits: kit differences, features, pricing, repository access, updates and development."}]]},"headers":[],"relativePath":"docs/reference/faq.md","filePath":"docs/reference/faq.md","lastUpdated":1790488620000}'),r={name:"docs/reference/faq.md"};function i(n,e,d,c,h,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h2><h3 id="what-is-the-difference-between-the-vue-react-and-svelte-kits" tabindex="-1">What is the difference between the Vue, React and Svelte kits? <a class="header-anchor" href="#what-is-the-difference-between-the-vue-react-and-svelte-kits" aria-label="Permalink to &quot;What is the difference between the Vue, React and Svelte kits?&quot;">​</a></h3><p>Only the frontend (<code>resources/js</code>). The Laravel backend (modules, tenancy, auth, permissions, migrations, translations, tests) is the same. Pick the frontend your team prefers. See <a href="/docs.html">Introduction</a>.</p><h3 id="is-there-a-billing-stripe-integration" tabindex="-1">Is there a billing / Stripe integration? <a class="header-anchor" href="#is-there-a-billing-stripe-integration" aria-label="Permalink to &quot;Is there a billing / Stripe integration?&quot;">​</a></h3><p>No. The kits do not include billing, subscriptions or payment processing for your customers.</p><h3 id="is-there-a-rest-api" tabindex="-1">Is there a REST API? <a class="header-anchor" href="#is-there-a-rest-api" aria-label="Permalink to &quot;Is there a REST API?&quot;">​</a></h3><p>No. All routes are Inertia web routes. There are no API tokens (Sanctum) or API endpoints.</p><h3 id="does-it-support-teams" tabindex="-1">Does it support teams? <a class="header-anchor" href="#does-it-support-teams" aria-label="Permalink to &quot;Does it support teams?&quot;">​</a></h3><p>Not as a feature. Each tenant is a separate workspace with its own users; spatie&#39;s teams mode is disabled in <code>config/permission.php</code>.</p><h3 id="can-tenants-use-their-own-custom-domains" tabindex="-1">Can tenants use their own custom domains? <a class="header-anchor" href="#can-tenants-use-their-own-custom-domains" aria-label="Permalink to &quot;Can tenants use their own custom domains?&quot;">​</a></h3><p>Out of the box, tenant domains are subdomains of <code>APP_DOMAIN</code> (<code>acme.your-domain.com</code>). A tenant can have several subdomains and one primary. See <a href="/docs/core/domains.html">Domains</a>.</p><h3 id="single-database-or-one-database-per-tenant" tabindex="-1">Single database or one database per tenant? <a class="header-anchor" href="#single-database-or-one-database-per-tenant" aria-label="Permalink to &quot;Single database or one database per tenant?&quot;">​</a></h3><p>One database per tenant (stancl/tenancy multi-database mode). See <a href="/docs/core/multi-tenancy.html">Multi-tenancy</a>.</p><h3 id="which-languages-are-included" tabindex="-1">Which languages are included? <a class="header-anchor" href="#which-languages-are-included" aria-label="Permalink to &quot;Which languages are included?&quot;">​</a></h3><p>17: English, Hindi, Spanish, French, German, Italian, Portuguese, Russian, Japanese, Korean, Turkish, Dutch, Indonesian, Bengali, Polish, Vietnamese and Thai. See <a href="/docs/core/localization.html">Localization</a>.</p><h3 id="is-ssr-enabled" tabindex="-1">Is SSR enabled? <a class="header-anchor" href="#is-ssr-enabled" aria-label="Permalink to &quot;Is SSR enabled?&quot;">​</a></h3><p>No. A <code>build:ssr</code> npm script exists, but the kits run as client-rendered Inertia apps by default.</p><h3 id="do-i-have-to-use-laravel-herd" tabindex="-1">Do I have to use Laravel Herd? <a class="header-anchor" href="#do-i-have-to-use-laravel-herd" aria-label="Permalink to &quot;Do I have to use Laravel Herd?&quot;">​</a></h3><p>No, but it is the easiest option because tenant subdomains (<code>*.vue.test</code>) work automatically. Any setup that serves the central domain and its wildcard subdomains works. See <a href="/docs/getting-started/requirements.html">Requirements</a>.</p><h3 id="can-i-use-sqlite-or-postgresql" tabindex="-1">Can I use SQLite or PostgreSQL? <a class="header-anchor" href="#can-i-use-sqlite-or-postgresql" aria-label="Permalink to &quot;Can I use SQLite or PostgreSQL?&quot;">​</a></h3><p><code>config/tenancy.php</code> registers database managers for SQLite, MySQL, MariaDB and PostgreSQL, and the test suite runs on in-memory SQLite. The kits are built and run against MySQL, which is the recommended choice.</p><h2 id="purchase-and-access" tabindex="-1">Purchase and access <a class="header-anchor" href="#purchase-and-access" aria-label="Permalink to &quot;Purchase and access&quot;">​</a></h2><h3 id="how-much-does-it-cost" tabindex="-1">How much does it cost? <a class="header-anchor" href="#how-much-does-it-cost" aria-label="Permalink to &quot;How much does it cost?&quot;">​</a></h3><p>The Vue kit is $29, the React kit $30 and the Svelte kit $33. The All Starter Kits bundle (Vue + React + Svelte) is $79, which saves $13. All are one-time payments with lifetime access. See <a href="/pricing.html">Pricing</a>.</p><h3 id="is-it-a-subscription" tabindex="-1">Is it a subscription? <a class="header-anchor" href="#is-it-a-subscription" aria-label="Permalink to &quot;Is it a subscription?&quot;">​</a></h3><p>No. You pay once and get lifetime access with weekly updates.</p><h3 id="how-do-i-pay" tabindex="-1">How do I pay? <a class="header-anchor" href="#how-do-i-pay" aria-label="Permalink to &quot;How do I pay?&quot;">​</a></h3><p>Through GitHub Sponsors. See <a href="/how-to-pay.html">How to pay</a>.</p><h3 id="how-quickly-do-i-get-access" tabindex="-1">How quickly do I get access? <a class="header-anchor" href="#how-quickly-do-i-get-access" aria-label="Permalink to &quot;How quickly do I get access?&quot;">​</a></h3><p>Immediately. Access is granted automatically: your GitHub account is invited to the repository as soon as the payment goes through. See <a href="/docs/purchase/repository-access.html">Repository access</a>.</p><h3 id="what-does-the-bundle-include" tabindex="-1">What does the bundle include? <a class="header-anchor" href="#what-does-the-bundle-include" aria-label="Permalink to &quot;What does the bundle include?&quot;">​</a></h3><p>Access to all three kit repositories (Vue, React and Svelte).</p><h3 id="how-do-i-get-updates" tabindex="-1">How do I get updates? <a class="header-anchor" href="#how-do-i-get-updates" aria-label="Permalink to &quot;How do I get updates?&quot;">​</a></h3><p>Updates are pushed weekly to your kit repository. Add it as the <code>upstream</code> remote and merge. See <a href="/docs/purchase/updates.html">Updates</a>.</p><h3 id="where-do-i-get-help" tabindex="-1">Where do I get help? <a class="header-anchor" href="#where-do-i-get-help" aria-label="Permalink to &quot;Where do I get help?&quot;">​</a></h3><p>Open an issue on your kit&#39;s GitHub repository. Check <a href="/docs/reference/troubleshooting.html">Troubleshooting</a> first.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><h3 id="where-do-i-add-a-new-feature" tabindex="-1">Where do I add a new feature? <a class="header-anchor" href="#where-do-i-add-a-new-feature" aria-label="Permalink to &quot;Where do I add a new feature?&quot;">​</a></h3><p>Create a new module in <code>Modules/&lt;Name&gt;/</code> with its own service provider, routes, controllers, Data classes and services, and register the provider in <code>bootstrap/providers.php</code>. Add pages in <code>resources/js/pages</code>. See <a href="/docs/core/architecture.html">Architecture</a>.</p><h3 id="how-do-i-add-a-page-that-only-tenants-see" tabindex="-1">How do I add a page that only tenants see? <a class="header-anchor" href="#how-do-i-add-a-page-that-only-tenants-see" aria-label="Permalink to &quot;How do I add a page that only tenants see?&quot;">​</a></h3><ol><li>Add the route in a module and protect it with <code>auth</code> and a tenant permission from <code>config/permissions/tenant/*.php</code>.</li><li>Add a menu entry to <code>Database\\Seeders\\tenant\\MenuSeeder</code>.</li><li>For strictly tenant-only routes, add stancl&#39;s <code>PreventAccessFromCentralDomains</code> middleware.</li></ol><h3 id="what-are-the-default-logins" tabindex="-1">What are the default logins? <a class="header-anchor" href="#what-are-the-default-logins" aria-label="Permalink to &quot;What are the default logins?&quot;">​</a></h3><p>One user per role, all with the password <code>password</code>:</p><table tabindex="0"><thead><tr><th>Role</th><th>Email</th></tr></thead><tbody><tr><td>Super Admin</td><td><code>super-admin@gmail.com</code></td></tr><tr><td>Admin</td><td><code>admin@gmail.com</code></td></tr><tr><td>Manager</td><td><code>manager@gmail.com</code></td></tr><tr><td>Employee</td><td><code>employee@gmail.com</code></td></tr><tr><td>User</td><td><code>user@gmail.com</code></td></tr></tbody></table><p>They are created by <code>DefaultUserSeeder</code> centrally and in every new tenant.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Change or remove the default users before going to production.</p></div><h3 id="do-the-kits-work-with-ai-coding-agents" tabindex="-1">Do the kits work with AI coding agents? <a class="header-anchor" href="#do-the-kits-work-with-ai-coding-agents" aria-label="Permalink to &quot;Do the kits work with AI coding agents?&quot;">​</a></h3><p>Yes. Each kit ships Laravel Boost guidelines (<code>AGENTS.md</code>, <code>CLAUDE.md</code>), skills in <code>.agents/skills</code> and <code>.claude/skills</code>, and an MCP configuration (<code>.mcp.json</code>). The Vue kit also has project rules in <code>.ai/rules</code>.</p>',49)])])}const m=a(r,[["render",i]]);export{p as __pageData,m as default};
